function fun () {
  const args = []
  const pathParams = options.pathParams || []
  const method = (options.apiMethod || 'get').toLowerCase()

  const upper = (value) => {
    if (!value) return ''
    return value.charAt(0).toUpperCase() + value.slice(1)
  }

  const pascal = (value) => (value || '').split(/[^a-zA-Z0-9]+/).filter(Boolean).map(upper).join('')

  const normalizeNamePath = (path) => (path || '').replace(/\$\{(?:pathParams\.)?(\w+)\}/g, '{$1}')

  const normalizeRuntimePath = (path) => {
    const getRuntimeName = (name) => (pathParams.length > 1 ? `pathParams.${name}` : name)
    return (path || '')
      .replace(/\$\{(?:pathParams\.)?(\w+)\}/g, (_, name) => '${' + getRuntimeName(name) + '}')
      .replace(/(^|[^$])\{(\w+)\}/g, (_, prefix, name) => prefix + '${' + getRuntimeName(name) + '}')
  }

  const buildResolvedFunctionName = () => {
    if (pathParams.length <= 1) return options.apiFunctionName

    const normalizedPath = normalizeNamePath(options.apiPath || '')
    const staticSegments = normalizedPath
      .split('/')
      .filter(Boolean)
      .filter((segment) => !/^\{.+\}$/.test(segment))
      .filter((segment) => !['admin', 'compendiums'].includes(segment))

    return `${method}${staticSegments.map(pascal).join('')}`
  }

  if (pathParams.length) {
    if (pathParams.length > 1) {
      args.push(`pathParams: Expand<${options.pathParamsType}>`)
    } else {
      args.push(`${pathParams[0].name}: ${options.buildParameters(pathParams[0])}`)
    }
  }

  if ((options.queryParams || []).length) {
    args.push(`params: Expand<${options.queryParamsType}>`)
  }

  if (!['get', 'delete', 'head', 'options'].includes(method) && options.haveReqBody) {
    args.push(`data: Expand<${options.dataParamsType}>`)
  }

  args.push('config?: Expand<ParticalUniAppRequestOptions>')

  const runtimePath = normalizeRuntimePath(options.apiPath)
  const quote = String.fromCharCode(96)
  const url = quote + runtimePath + quote
  const bodyParams = ['get', 'delete', 'head', 'options'].includes(method)
    ? (options.queryParams.length ? 'params, ' : '{}, ')
    : (options.haveReqBody ? 'data, ' : '{}, ')
  const newline = String.fromCharCode(10)
  const resolvedFunctionName = buildResolvedFunctionName()

  return `export const ${resolvedFunctionName} = async (${args.join(', ')}): Promise<Expand<${options.apiFunctionName}Res>> => {${newline}    const _config = baseURL ? { baseURL, ...config } : config${newline}    return http.${method}(${url}, ${bodyParams}_config)${newline}}`
}
fun()
